@router.post({{path}}, response_model=BatchRead, status_code=201)
def create_batch(data: BatchCreate, db: Annotated[Session, Depends(session_provider)]) -> BatchRead:
    """Create batch."""
    parent = Parent(**model_values(data.parent))
    children = []
    try:
        db.add(parent)
        db.flush()
        for item in data.children:
            child = Child({{foreign_key}}=parent.id, **model_values(item))
            db.add(child)
            db.flush()
            children.append(child)
        db.commit()
    except IntegrityError as exc:
        integrity_failure(db, exc)
    db.refresh(parent)
    for child in children:
        db.refresh(child)
    return BatchRead.model_validate({"parent": parent, "children": children})
